mapper.select:
select COUNT(*) from (select * from (select cm.* ,GROUP_CONCAT(al.model_name) AS modelName, GROUP_CONCAT(ky.name) as alarmType from ( (camera_manager as cm left join algorithm_manager as al on cm.id = al.belong_to) left join ky_category as ky on ky.id = al.model_name) WHERE cm.camera_status ='1' GROUP BY cm.id ) as temp
and temp.camera_ownership = #{cameraManager.cameraOwnership}
and temp.location in ( SELECT au.id FROM ( SELECT * FROM ky_category WHERE pid IS NOT NULL ) au, (SELECT @pid := #{cameraManager.location}) pd WHERE FIND_IN_SET(pid, @pid) > 0 AND @pid := concat(@pid, ',', id) UNION SELECT id FROM ky_category WHERE id = #{cameraManager.location} )
and temp.factory = #{cameraManager.factory}
and temp.camera_name like CONCAT('%',#{cameraManager.cameraName},'%')
and
LOCATE (#{category},temp.modelName) > 0
) as tt

SELECT cm.*, (SELECT ky.NAME FROM ky_category ky WHERE ky.id = cm.location) AS locationName, (SELECT sy.item_text FROM sys_dict_item sy LEFT JOIN sys_dict sd on sd.id = sy.dict_id where sd.dict_code = 'factory_name' and sy.item_value = cm.factory) AS factoryName, (SELECT dm.device_name FROM device_management dm WHERE cm.camera_ownership = dm.id) as deviceName, (SELECT sy.item_text FROM sys_dict_item sy LEFT JOIN sys_dict sd on sd.id = sy.dict_id where sd.dict_code = 'stream_type' and sy.item_value = cm.stream_type) AS streamType, (SELECT sy.item_text FROM sys_dict_item sy LEFT JOIN sys_dict sd on sd.id = sy.dict_id where sd.dict_code = 'stream_format' and sy.item_value = cm.stream_format) AS streamFormat, (SELECT cf.camera_type FROM camera_factory cf WHERE cf.id = cm.camera_type )as cameraType, if(cm.camera_status ='1','在线','离线') as cameraStatus FROM camera_manager AS cm
and cm.camera_ownership = #{cameraManager.cameraOwnership}
and cm.location = #{cameraManager.location}

SELECT * FROM `camera_manager` INNER JOIN `algorithm_manager` ON camera_manager.id = algorithm_manager.belong_to AND algorithm_manager.group_id IN
#{groupId}
AND camera_ownership = #{deviceId} GROUP BY camera_manager.id
